"""Background video: a clip from your library, or a generated animation when there is none.

* `auto`      - an unused library clip that is long enough, else a generated gradient
* `gradient`  - slowly moving colour gradient (generated by ffmpeg, no files needed)
* `life`      - calm, dark "Game of Life" animation (generated)
* a file path - that exact clip

The library is just a folder of videos registered in the database (`videobot library add`),
optionally filled with free stock clips from Pexels (`videobot library pexels "ocean"`).
"""

from __future__ import annotations

import json
import os
import random
import subprocess
import urllib.parse
import urllib.request
from dataclasses import dataclass
from pathlib import Path

from .config import home
from .db import mark_used

VIDEO_EXT = {".mp4", ".mov", ".mkv", ".webm", ".m4v", ".avi"}
PALETTES = [
    ("0x0f2027", "0x203a43", "0x2c5364", "0x7f5a83"),
    ("0x1a1a2e", "0x16213e", "0x0f3460", "0x533483"),
    ("0x0b3d2e", "0x14532d", "0x166534", "0x0e7490"),
    ("0x3b0a45", "0x5b1a5e", "0x8e2c6b", "0xc2410c"),
]


@dataclass
class Background:
    """ffmpeg input arguments for the background, plus the clip id if it came from the library."""
    args: list[str]
    label: str
    clip_id: int | None = None
    credit: str = ""        # attribution for the clip (goes into the video description)


def generated(style: str, seed: int | None = None) -> Background:
    rnd = random.Random(seed)
    if style == "life":
        src = ("life=s=180x320:r=30:ratio=0.07:mold=25:life_color=#3a7ca5:death_color=#0b1026:"
               "mold_color=#16324f,scale=1080:1920:flags=neighbor,gblur=sigma=2")
    else:
        c = rnd.choice(PALETTES)
        # drawn small and scaled up: smooth colour fields and cheap to render
        src = (f"gradients=s=135x240:r=30:speed=0.004:nb_colors=4:c0={c[0]}:c1={c[1]}:c2={c[2]}:c3={c[3]}:"
               f"type=radial:seed={rnd.randint(0, 9999)},gblur=sigma=6,scale=1080:1920:flags=bicubic")
    return Background(["-f", "lavfi", "-i", src], f"generated:{style}")


def choose(con, channel: str, need: float, spec: str = "auto", seed: int | None = None) -> Background:
    """Pick the background for a video that needs `need` seconds of footage."""
    if spec in ("gradient", "life"):
        return generated(spec, seed)
    if spec != "auto":
        path = Path(spec).expanduser()
        if not path.exists():
            raise SystemExit(f"Background clip not found: {path}")
        row = con.execute("SELECT * FROM clips WHERE path = ?", (str(path.resolve()),)).fetchone()
        if row:  # a registered clip: keep its credit and usage tracking
            return _from_file(path, need, row["duration"], row["id"], seed, row["license"])
        return _from_file(path, need, probe(path)["duration"])
    rows = con.execute(
        """SELECT c.* FROM clips c WHERE c.duration >= ? AND c.id NOT IN
           (SELECT item_id FROM usage WHERE kind = 'clip' AND channel = ?)""",
        (need + 1, channel),
    ).fetchall()
    if not rows:  # every long-enough clip used by this channel: allow reuse
        rows = con.execute("SELECT * FROM clips WHERE duration >= ?", (need + 1,)).fetchall()
    if not rows:
        return generated("gradient", seed)
    row = random.Random(seed).choice(rows)
    return _from_file(Path(row["path"]), need, row["duration"], row["id"], seed, row["license"])


def _from_file(path: Path, need: float, length: float, clip_id: int | None = None, seed=None,
               credit: str = "") -> Background:
    start = random.Random(seed).uniform(0, max(0.0, length - need - 1)) if length > need + 1 else 0
    loop = ["-stream_loop", "-1"] if length < need else []
    return Background([*loop, "-ss", f"{start:.2f}", "-i", str(path)], f"{path.name} @ {start:.0f}s", clip_id, credit)


def remember(con, channel: str, bg: Background, video: str) -> None:
    if bg.clip_id is not None:
        mark_used(con, channel, "clip", bg.clip_id, video)


# ------------------------------------------------------------------ library

def probe(path: Path) -> dict:
    out = subprocess.run(
        ["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries",
         "stream=width,height:format=duration", "-of", "json", str(path)],
        capture_output=True, text=True,
    )
    data = json.loads(out.stdout or "{}")
    stream = (data.get("streams") or [{}])[0]
    return {"duration": float(data.get("format", {}).get("duration", 0) or 0),
            "width": stream.get("width"), "height": stream.get("height")}


def add_folder(con, folder: Path, license: str = "") -> int:
    """Register every video in `folder` (recursively). Returns the number of new clips.

    `license` is the clip credit, e.g. "Gameplay by X (CC BY 3.0) - https://...". It is added
    to the description of every video that uses one of these clips."""
    added = 0
    for p in sorted(Path(folder).expanduser().rglob("*")):
        if p.suffix.lower() in VIDEO_EXT and not p.name.startswith("."):
            info = probe(p)
            if info["duration"] > 0:
                cur = con.execute(
                    "INSERT OR IGNORE INTO clips (path, duration, width, height, license) VALUES (?,?,?,?,?)",
                    (str(p.resolve()), info["duration"], info["width"], info["height"], license))
                added += cur.rowcount
    con.commit()
    return added


def pexels(con, query: str, count: int = 5, api_key: str | None = None) -> int:
    """Download free portrait stock clips from Pexels (needs a free API key: PEXELS_API_KEY)."""
    key = api_key or os.environ.get("PEXELS_API_KEY")
    if not key:
        raise SystemExit("Set PEXELS_API_KEY (free at https://www.pexels.com/api/) to download stock clips.")
    url = "https://api.pexels.com/videos/search?" + urllib.parse.urlencode(
        {"query": query, "orientation": "portrait", "per_page": count, "size": "medium"})
    req = urllib.request.Request(url, headers={"Authorization": key, "User-Agent": "videobot/0.1"})
    videos = json.load(urllib.request.urlopen(req, timeout=30))["videos"]
    folder = home() / "library" / "pexels"
    folder.mkdir(parents=True, exist_ok=True)
    for v in videos:
        files = [f for f in v["video_files"] if f.get("height") and f["height"] <= 1920 and f["file_type"] == "video/mp4"]
        if not files:
            continue
        best = max(files, key=lambda f: f["height"])
        target = folder / f"pexels-{v['id']}.mp4"
        if not target.exists():
            urllib.request.urlretrieve(best["link"], target)
    return add_folder(con, folder, license="Pexels License")
